from datetime import date, datetime, timedelta

import config
import models


def week_start(day):
    """Return the Monday of the supplied date or datetime's week."""
    if isinstance(day, datetime):
        day = day.date()
    if not isinstance(day, date):
        raise ValueError('Week day must be a date.')
    return day - timedelta(days=day.weekday())


def week_days(monday):
    """Return the week's seven dates including Saturday and Sunday."""
    monday = week_start(monday)
    return [monday + timedelta(days=offset) for offset in range(config.DAYS_PER_WEEK)]


def navigation_bounds(first_date, last_date):
    """Return inclusive Monday bounds, or (None,None) for an empty catalogue.

    :param first_date: earliest event date, or None for an empty catalogue
    :param last_date: latest event date, or None for an empty catalogue
    :return: first and last allowed Mondays
    """
    if first_date is None and last_date is None:
        return None, None
    if first_date is None or last_date is None or last_date < first_date:
        raise ValueError('Navigation requires ordered event dates.')
    return week_start(first_date), week_start(last_date)


def _validated_intervals(intervals):
    """Copy positive naive datetime intervals without changing the caller's collection."""
    result = []
    for start, end in intervals:
        if not isinstance(start, datetime) or not isinstance(end, datetime):
            raise ValueError('Busy intervals must use datetime boundaries.')
        if start.tzinfo is not None or end.tzinfo is not None or end <= start:
            raise ValueError('Busy intervals must be positive and use naive Zurich time.')
        result.append((start, end))
    return result


def merge_intervals(intervals):
    """Return sorted intervals with all overlaps and touching endpoints merged.

    :param intervals: iterable of positive naive (start, end) datetime tuples
    :return: a new chronological list of disjoint intervals
    """
    # Course: U03 s3 – sort a copy before a single pass over the intervals.
    ordered = sorted(_validated_intervals(intervals), key=lambda interval: interval[0])
    merged = []
    for start, end in ordered:
        if merged and start <= merged[-1][1]:
            previous_start, previous_end = merged[-1]
            merged[-1] = (previous_start, max(previous_end, end))
        else:
            merged.append((start, end))
    return merged


def find_gaps_for_day(day, busy_intervals, window_start=config.DAY_WINDOW_START,
                      window_end=config.DAY_WINDOW_END, min_gap_minutes=config.MIN_GAP_MINUTES):
    """Find free intervals of at least the minimum duration inside one day window.

    :param day: date to analyze
    :param busy_intervals: arbitrary-order (start,end) local datetime tuples
    :param window_start: opening time, normally 07:00
    :param window_end: closing time, normally 23:00
    :param min_gap_minutes: minimum duration, normally 60 minutes
    :return: chronological Gap objects, following SPEC section 10.2
    """
    if window_end <= window_start or min_gap_minutes <= 0:
        raise ValueError('Day window and minimum gap duration must be positive.')
    # initialization phase
    beginning, finish = datetime.combine(day, window_start), datetime.combine(day, window_end)
    clipped = []
    for start, end in _validated_intervals(busy_intervals):
        start, end = max(start, beginning), min(end, finish)
        if end > start:
            clipped.append((start, end))
    result, cursor = [], beginning
    # processing phase: a final sentinel handles the trailing interval with the same rule.
    for start, end in merge_intervals(clipped) + [(finish, finish)]:
        if start - cursor >= timedelta(minutes=min_gap_minutes):
            result.append(models.Gap(day, cursor, start))
        cursor = max(cursor, end)
    # termination phase
    return result


def find_gaps_for_week(monday, busy_intervals):
    """Return seven days of gaps, clipping overnight intervals separately for each date."""
    intervals, result = list(busy_intervals), []
    for day in week_days(monday):
        result.extend(find_gaps_for_day(day, intervals))
    return result


def placement_problem(event):
    """Return a Beyond-your-gaps reason or None for a placeable event."""
    if event.location_type not in config.PLACEABLE_LOCATION_TYPES:
        return f'Off-site: {event.location}'
    if event.event_type in config.NOT_PLACEABLE_EVENT_TYPES:
        return 'Trip'
    if event.is_multi_day():
        return 'Multi-day'
    beginning = datetime.combine(event.start.date(), config.DAY_WINDOW_START)
    finish = datetime.combine(event.start.date(), config.DAY_WINDOW_END)
    finish += timedelta(minutes=config.OVERLAP_TOLERANCE_MINUTES)
    if event.start < beginning or event.end > finish:
        return 'Outside your day window'
    return None


def assign_events_to_gaps(events, gaps, confirmed_ids, now=None):
    """Return (gap-ID to events, beyond list) while assigning each future event only once.

    :param events: occurrences in the visible week
    :param gaps: chronological Gap objects
    :param confirmed_ids: event IDs already represented by confirmed blocks
    :param now: injected local clock, default current Zurich time
    :return: placement dictionary and (event,reason) pairs; plain clashes are omitted
    """
    now, confirmed_ids = config.local_now(now), set(confirmed_ids)
    placed, beyond = {}, []
    for gap in gaps:
        placed[gap.gap_id] = []
    for event in events:
        if event.status in config.HIDDEN_STATUSES or event.event_id in confirmed_ids:
            continue
        if event.start <= now:
            continue
        reason = placement_problem(event)
        if reason is not None:
            beyond.append((event, reason))
            continue
        for gap in gaps:
            if gap.fits(event):
                placed[gap.gap_id].append(event)
                break
    return placed, beyond
